1	import type { AgentrackError } from "../core/errors";
2	import type {
3	  BlockageInfo,
4	  CommentId,
5	  ComputedComment,
6	  ComputedIssue,
7	  IndexEntry,
8	  IssueId,
9	  IssueStatus,
10	  UserInfo,
11	} from "./index";
12	
13	// ─── Init ───────────────────────────────────────────────────────────
14	
15	/** Result of initializing a new tracker directory. */
16	export type InitResult =
17	  | { result: "OK"; path: string }
18	  | { result: "ALREADY_INITIALIZED"; path: string };
19	
20	// ─── Create ─────────────────────────────────────────────────────────
21	
22	/** Parameters for creating a new issue. */
23	export interface CreateParams {
24	  /** The issue title (required). */
25	  title: string;
26	  /** Optional description, defaults to "". */
27	  description?: string;
28	  /** Optional assignee, defaults to null. */
29	  assignee?: string;
30	  /** Optional tags, defaults to []. */
31	  tags?: string[];
32	  /** Initial status, defaults to "idea". */
33	  status?: IssueStatus;
34	  /** Priority 1-5, defaults to 3. */
35	  priority?: 1 | 2 | 3 | 4 | 5;
36	  /** Optional parent issue ID for hierarchy. */
37	  parentId?: IssueId | null;
38	  /** Custom file path for the issue (relative to tracker dir). */
39	  path?: string;
40	  /** Override author (resolved by auth layer if not provided). */
41	  author?: string;
42	}
43	
44	/** Result of creating a new issue. */
45	export type CreateResult = { id: IssueId } | AgentrackError;
46	
47	// ─── Update ─────────────────────────────────────────────────────────
48	
49	/** Parameters for updating an existing issue. At least one field must be provided. */
50	export interface UpdateParams {
51	  /** New title. */
52	  title?: string;
53	  /** New description. */
54	  description?: string;
55	  /** New status. */
56	  status?: IssueStatus;
57	  /** New assignee, or null to clear. */
58	  assignee?: string | null;
59	  /** New tags (replaces existing). */
60	  tags?: string[];
61	  /** New priority (1-5). */
62	  priority?: 1 | 2 | 3 | 4 | 5;
63	  /** New parent ID, null to detach from parent. */
64	  parentId?: IssueId | null;
65	  /** Override author (resolved by auth layer if not provided). */
66	  author?: string;
67	}
68	
69	/** Result of updating an issue. */
70	export type UpdateResult = { result: "OK" } | AgentrackError;
71	
72	// ─── List ───────────────────────────────────────────────────────────
73	
74	/** Parameters for listing issues with optional filters. */
75	export interface ListParams {
76	  /** Filter by status. "open" = all except closed. */
77	  status?: IssueStatus | "open";
78	  /** Filter by assignee name. */
79	  assignee?: string;
80	  /** AND filter — issue must have ALL specified tags. */
81	  tags?: string[];
82	  /** Filter by parent ID. null = top-level issues only. */
83	  parentId?: IssueId | null;
84	}
85	
86	/** Result of listing issues — sorted by priority ASC, impact DESC, id ASC. */
87	export type ListResult = IndexEntry[];
88	
89	// ─── View ───────────────────────────────────────────────────────────
90	
91	/** Result of viewing an issue's full computed state. */
92	export type ViewResult = ComputedIssue | AgentrackError;
93	
94	// ─── Next ───────────────────────────────────────────────────────────
95	
96	/** Result of the next command — the recommended issue to work on, or no issues available. */
97	export type NextResult = ComputedIssue | { result: "NO_ISSUES_AVAILABLE"; message: string };
98	
99	// ─── History ────────────────────────────────────────────────────────
100	
101	import type { Event } from "./event";
102	
103	export type { Event };
104	
105	/** Result of retrieving an issue's raw event history. */
106	export type HistoryResult = Event[] | AgentrackError;
107	
108	// ─── Comments ───────────────────────────────────────────────────────
109	
110	/** Parameters for adding a comment to an issue. */
111	export interface CommentAddParams {
112	  /** The comment content. */
113	  content: string;
114	  /** Override author (resolved by auth layer if not provided). */
115	  author?: string;
116	}
117	
118	/** Result of adding a comment. */
119	export type CommentAddResult = { result: "OK"; commentId: CommentId } | AgentrackError;
120	
121	/** Parameters for updating an existing comment. */
122	export interface CommentUpdateParams {
123	  /** The new comment content. */
124	  content: string;
125	  /** Override author (resolved by auth layer if not provided). */
126	  author?: string;
127	}
128	
129	/** Result of updating a comment. */
130	export type CommentUpdateResult = { result: "OK" } | AgentrackError;
131	
132	/** Parameters for deleting a comment. */
133	export interface CommentDeleteParams {
134	  /** Override author (resolved by auth layer if not provided). */
135	  author?: string;
136	}
137	
138	/** Result of deleting a comment. */
139	export type CommentDeleteResult = { result: "OK" } | AgentrackError;
140	
141	/** Result of listing comments for an issue. */
142	export type CommentsListResult = ComputedComment[] | AgentrackError;
143	
144	// ─── Blockages ──────────────────────────────────────────────────────
145	
146	/** Parameters for adding blockage dependencies. */
147	export interface BlockagesAddParams {
148	  /** IDs of the blocker issues. */
149	  blockerIds: IssueId[];
150	  /** Override author (resolved by auth layer if not provided). */
151	  author?: string;
152	}
153	
154	/** Result of adding blockages. */
155	export type BlockagesAddResult = { result: "OK" } | AgentrackError;
156	
157	/** Parameters for resolving blockage dependencies. */
158	export interface BlockagesResolveParams {
159	  /** IDs of the blocker issues to resolve. */
160	  blockerIds: IssueId[];
161	  /** Override author (resolved by auth layer if not provided). */
162	  author?: string;
163	}
164	
165	/** Result of resolving blockages. */
166	export type BlockagesResolveResult = { result: "OK" } | AgentrackError;
167	
168	/** Parameters for deleting blockage dependencies. */
169	export interface BlockagesDeleteParams {
170	  /** IDs of the blocker issues to delete. */
171	  blockerIds: IssueId[];
172	  /** Override author (resolved by auth layer if not provided). */
173	  author?: string;
174	}
175	
176	/** Result of deleting blockages. */
177	export type BlockagesDeleteResult = { result: "OK" } | AgentrackError;
178	
179	/** Result of listing blockage info for an issue. */
180	export type BlockagesListResult = BlockageInfo | AgentrackError;
181	
182	// ─── Users ──────────────────────────────────────────────────────────
183	
184	/** Result of registering a new user. */
185	export type UsersRegisterResult =
186	  | { result: "OK"; name: string; token: string }
187	  | { result: "USER_ALREADY_EXISTS"; message: string };
188	
189	/** Result of listing users — tokens are never included. */
190	export type UsersListResult = UserInfo[];
191	
192	/** Result of revoking a user. */
193	export type UsersRevokeResult = { result: "OK" } | { result: "USER_NOT_FOUND"; message: string };
